def toposort(nodes, edges):
    import heapq
    # Build adjacency list and indegree counts
    adjacency = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}
    for src, dest in edges:
        if dest not in adjacency[src]:
            adjacency[src].add(dest)
            indegree[dest] += 1

    # Initialize min-heap with nodes having indegree 0
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nb in adjacency[node]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(heap, nb)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")
    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    result = []
    current = []
    current_sum = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_sum + weight <= limit:
            current.append(name)
            current_sum += weight
        else:
            result.append(current)
            current = [name]
            current_sum = weight
    if current:
        result.append(current)
    return result
